/*
 * Play Store hardening for the native customer app (lk.blynk.customer), config-plugin only
 * (android/ is generated by `expo prebuild` and gitignored). Two small things app.json cannot say:
 *
 *  1. Remove expo-location's LocationTaskService from the merged manifest. It is a foreground
 *     service of type "location" that only background location updates use. Blynk asks for
 *     foreground-only location (one GPS fix for the delivery pin), so the service is dead code, and
 *     a foreground-service declaration in the manifest invites the Play "foreground service
 *     permissions" declaration and a policy review we do not need. (The FOREGROUND_SERVICE
 *     permissions are not in the manifest, so the service could never start anyway.)
 *  2. Ask Gradle for native debug symbols (SYMBOL_TABLE) in the release bundle, so Play Console shows
 *     readable native crash stacks and does not warn "no debug symbols uploaded".
 *
 * Both are idempotent. The pure helpers are exported for the test
 * (src/blynk/lib/withBlynkPlayHardening.test.ts).
 */
const { withAndroidManifest, withAppBuildGradle } = require('expo/config-plugins');

const TOOLS_NS = 'http://schemas.android.com/tools';
const UNUSED_SERVICES = ['expo.modules.location.services.LocationTaskService'];
const SYMBOLS_MARK = '// blynk-native-debug-symbols';

/** Add `<service android:name=X tools:node="remove"/>` for each name (once) and declare the tools namespace. */
function removeServices(manifestDoc, names = UNUSED_SERVICES) {
  const manifest = manifestDoc.manifest;
  manifest.$ = manifest.$ || {};
  if (!manifest.$['xmlns:tools']) manifest.$['xmlns:tools'] = TOOLS_NS;

  const app = Array.isArray(manifest.application) ? manifest.application[0] : undefined;
  if (!app) throw new Error('withBlynkPlayHardening: no <application> in the manifest');
  app.service = app.service || [];

  for (const name of names) {
    const existing = app.service.find((s) => s.$ && s.$['android:name'] === name);
    if (existing) existing.$['tools:node'] = 'remove';
    else app.service.push({ $: { 'android:name': name, 'tools:node': 'remove' } });
  }
  return manifestDoc;
}

/** Put `ndk { debugSymbolLevel 'SYMBOL_TABLE' }` at the top of the release build type (once). */
function addDebugSymbols(gradle) {
  if (gradle.includes(SYMBOLS_MARK)) return gradle;
  const re = /(buildTypes \{[\s\S]*?\n(\s*)release \{\n)/;
  if (!re.test(gradle)) return gradle; // template changed: leave the file alone rather than break the build
  return gradle.replace(
    re,
    (m, head, indent) => `${head}${indent}    ${SYMBOLS_MARK}\n${indent}    ndk { debugSymbolLevel 'SYMBOL_TABLE' }\n`
  );
}

function withBlynkPlayHardening(config) {
  config = withAndroidManifest(config, (cfg) => {
    cfg.modResults = removeServices(cfg.modResults);
    return cfg;
  });
  return withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = addDebugSymbols(cfg.modResults.contents);
    return cfg;
  });
}

module.exports = withBlynkPlayHardening;
module.exports.removeServices = removeServices;
module.exports.addDebugSymbols = addDebugSymbols;
module.exports.UNUSED_SERVICES = UNUSED_SERVICES;
